using Myra.Graphics2D.UI.Styles;
using Microsoft.Xna.Framework;
using System.Globalization;

namespace OpenGothic.UI
{
	public partial class DebugOverlay
	{
		private const float FpsInterval = 0.5f;

		private float _elapsed;
		private int _frames;
		private int _fps;

		public DebugOverlay()
		{
			BuildUI();
		}

		private static readonly NumberFormatInfo NumberFormat = new NumberFormatInfo
		{
			NumberGroupSeparator = ",",
			NumberGroupSizes = new[] { 3 }
		};

		public void Update(GameTime gameTime, Camera camera, Renderer renderer)
		{
			_elapsed += (float)gameTime.ElapsedGameTime.TotalSeconds;
			++_frames;

			if (_elapsed >= FpsInterval)
			{
				_fps = (int)(_frames / _elapsed);
				_elapsed = 0;
				_frames = 0;
			}

			var position = camera.Position;

			_labelFps.Text = Format("FPS: {0}", _fps);
			_labelPosition.Text = Format("Position: {0:0.0}, {1:0.0}, {2:0.0}", position.X, position.Y, position.Z);
			_labelDrawCalls.Text = Format("Draw calls: {0:N0}", renderer.DrawCalls);
			_labelTriangles.Text = Format("Triangles: {0:N0}", renderer.Triangles);
		}

		private static string Format(string format, params object[] args)
		{
			return string.Format(NumberFormat, format, args);
		}
	}
}
